// Stock measurements the previous run left open. No overlay and no behaviour hook.
// The exec trace starts before the opening key and before MENU. The unique-call
// cap is 20000. AF Target Mode Settings is entered and each row is opened with
// Right, watching 0x1dd1 indices 2-9. A native setter write then enables every
// 0x5a11 slot so the stock direct screen can show a custom zone.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/stock_gaps_f1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/stock_gaps_f1.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const OUT = resolve('work/out/stock-gaps-f1.jsonl');
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const CALL_CAP = 20000;
const DEADLINE = Date.now() + 22 * 60 * 1000;
const WATCH = new Set([
  0x99a1, 0x9a41, 0x5962, 0x1dd1, 0x1de1, 0x1df1, 0x1e01,
  0xdfa1, 0x99d2, 0x9fa1, 0x84d1, 0x88b2, 0x90d1, 0xe91, 0x1db1, 0x1dc1, 0x5a11, 0x90a1,
]);

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { IMAGE_BASE } = await use('src/fw/model.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');
const { fileNvram } = await use('host/nvram.mjs');
const { setExecTrace } = await use('src/core/cpu.mjs');
const { setForceHelper } = await use('src/core/interp.mjs');

function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const seeds = [fileURLToPath(import.meta.url)];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  IMPORT_RE.lastIndex = 0;
  let match;
  const text = data.toString('utf8');
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next && !seen.has(next)) queue.push(next);
  }
}
mkdirSync(resolve('work/out'), { recursive: true });
writeFileSync(resolve('work/out/import-inventory-f1.json'), JSON.stringify({
  note: 'SHA-256 of this script before the stock session. Emulator modules are hashed by the acceptance runner.',
  hashed: 'execution',
  script: [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), ...meta })),
}, null, 2) + '\n');

const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({
    step: row.step, screen: row.screen, state: row.stateName, diff: row.diff,
    calls: row.callCount, capped: row.callCapped, zone: row.zone, custom: row.customTouched,
    error: row.error || row.pressError || null,
  }));
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const hex = (v) => '0x' + (v >>> 0).toString(16);
const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const nv = fileNvram(resolve('work/out/nvram-stock-gaps-f1.json'));
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, nvram: nv, patch: null, patchRanges: [], loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

function diffCells(a, b, path = '', out = []) {
  if (Array.isArray(a) && Array.isArray(b)) {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) out.push([path + '[' + i + ']', a[i], b[i]]);
    return out;
  }
  if (a && b && typeof a === 'object') {
    for (const k of Object.keys(a)) diffCells(a[k], b[k], path ? path + '.' + k : k, out);
    return out;
  }
  if (a !== b) out.push([path, a, b]);
  return out;
}
function titleHash(frame) {
  const [w, h, words] = frame;
  const y1 = Math.max(1, Math.min(h, Math.floor(h * 0.16)));
  const x0 = Math.floor(w * 0.22);
  const x1 = Math.floor(w * 0.78);
  const buf = Buffer.alloc((x1 - x0) * y1 * 4);
  let o = 0;
  for (let y = 0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      buf.writeUInt32LE(words[y * w + x] >>> 0, o);
      o += 4;
    }
  }
  return { w, h, x0, y0: 0, x1, y1, sha256: createHash('sha256').update(buf).digest('hex') };
}
function frameHash(frame) {
  const words = frame[2];
  const buf = Buffer.alloc(words.length * 4);
  for (let i = 0; i < words.length; i++) buf.writeUInt32LE(words[i] >>> 0, i * 4);
  return createHash('sha256').update(buf).digest('hex');
}

let failed = null;
try {
  pl.open_session();
  const s = pl.session;
  const l = s.lab;
  const gate = { reading: false, on: false };
  const sets = [];
  let setDropped = 0;
  let tracing = false;
  let lastPc = 0;
  let lastOp = 0;
  let callEvents = 0;
  let callCapped = false;
  const callEntries = [];
  const seenCalls = new Set();
  l.observe(native(SETTER), (_lab, r) => {
    if (!gate.on || gate.reading) return;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    if (!WATCH.has(key)) return;
    if (sets.length >= 80) { setDropped += 1; return; }
    sets.push({ key: hex(key), index, a1: hex(r.a1 >>> 0), caller: hex(r.mdr >>> 0) });
  }, 'obs-setter-f1');
  setExecTrace((pc, op) => {
    if (!tracing) return;
    const p = pc >>> 0;
    const delta = (p - lastPc) >>> 0;
    if (lastPc && (delta > 6 || p < lastPc)) {
      let call = lastOp === 0xdd || lastOp === 0xcd;
      if (!call && (lastOp === 0xfc || lastOp === 0xfa)) {
        try { call = l.sim.read(lastPc, 2)[1] === 0xff; } catch { /* unreadable */ }
      }
      if (call) {
        callEvents += 1;
        if (!seenCalls.has(p)) {
          if (callEntries.length >= CALL_CAP) callCapped = true;
          else { seenCalls.add(p); callEntries.push(hex(p)); }
        }
      }
    }
    lastPc = p;
    lastOp = op & 0xff;
  });
  const readByte = (addr) => l.sim.read(addr, 1)[0];
  const callSaved = (fn) => {
    const saved = l.sim.registers();
    const was = tracing;
    tracing = false;
    gate.reading = true;
    try { return fn(); }
    finally { gate.reading = false; tracing = was; l.sim.reset(saved); }
  };
  const readKey = (key, index) => callSaved(() => l.call(native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
  const writeKey = (key, index, value) => callSaved(() => l.call(native(SETTER), { d0: key, d1: index, a1: value }, null, null, 200000));
  const arr = (key, n) => Array.from({ length: n }, (_, i) => readKey(key, i));
  const cells = () => ({
    k99a1: arr(0x99a1, 8),
    k9a41: arr(0x9a41, 2),
    k5962: arr(0x5962, 6),
    k1dd1: arr(0x1dd1, 10),
    k1de1: arr(0x1de1, 8),
    k84d1: readKey(0x84d1, 0),
    k88b2: readKey(0x88b2, 0),
    k90d1: arr(0x90d1, 8),
    k99d2: arr(0x99d2, 3),
    kdfa1: readKey(0xdfa1, 0),
    k9fa1: arr(0x9fa1, 3),
    k5a11: arr(0x5a11, 11),
    k1db1: readKey(0x1db1, 0),
    k1dc1: readKey(0x1dc1, 0),
    ke91: readKey(0xe91, 3),
    k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
  });
  const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
  const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(400); };
  const dial = (which, n) => { s.dial_input(which, n); s.camapp.pump(); idle(400); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 8 });
  let shotN = 0;
  let before = null;
  const clearCalls = () => {
    callEntries.length = 0; seenCalls.clear(); callEvents = 0; callCapped = false; lastPc = 0; lastOp = 0;
    sets.length = 0; setDropped = 0;
  };
  const timeLeft = () => Date.now() < DEADLINE;
  const snap = (step, extra = {}) => {
    let texts = [];
    let frame = null;
    let textError = null;
    try {
      const scr = walk.read();
      texts = scr.texts.map((t) => t.text);
      frame = scr.frame;
    } catch (e) {
      textError = String(e && e.message || e);
      try { frame = s.frame('boundary'); } catch (e2) { textError += ' frame: ' + String(e2 && e2.message || e2); }
    }
    if (!frame) throw new Error('screenshot failed at ' + step + ': ' + textError);
    const file = resolve('work/out/stock-gaps-f1-' + String(shotN).padStart(2, '0') + '-' + step.replace(/[^a-z0-9-]+/gi, '_') + '.png');
    shotN += 1;
    write_png(file, frame[0], frame[1], words_to_rgb(frame[2]));
    const now = cells();
    const diff = before ? diffCells(before, now) : [];
    const customTouched = diff.some((d) => String(d[0]).startsWith('k1dd1[') && Number(String(d[0]).slice(6, -1)) >= 2);
    let stateName = null;
    let state = null;
    try { state = l.state(); stateName = l.state_names.get(state) ?? null; } catch { /* state unread */ }
    const row = {
      hook: 'observe', role: 'observe', step,
      screen: s.screen(), state, stateName, texts, textError,
      screenshot: file.split(/[/\\]/).pop(),
      title: titleHash(frame),
      frameHash: frameHash(frame),
      cells: now, diff,
      zone: now.k99a1[1],
      customTouched,
      sets: sets.slice(), setDropped,
      calls: extra.keepCalls ? callEntries.slice() : undefined,
      callCount: callEntries.length, callEvents, callCapped, callCap: CALL_CAP,
      ...extra.rest,
    };
    emit(row);
    before = now;
    return row;
  };
  const act = (step, fn, extra) => {
    clearCalls();
    let pressError = null;
    try { fn(); } catch (e) { pressError = String(e && e.message || e); }
    const row = snap(step, extra);
    if (pressError) row.pressError = pressError;
    return row;
  };
  const traced = (step, fn) => {
    clearCalls();
    tracing = true;
    setForceHelper(true);
    let pressError = null;
    try { fn(); }
    catch (e) { pressError = String(e && e.message || e); }
    finally { tracing = false; setForceHelper(false); }
    const row = snap(step, { keepCalls: true });
    if (pressError) row.pressError = pressError;
    return row;
  };
  const escapeShooting = () => {
    for (let i = 0; i < 8; i++) {
      if (s.screen() === 'shooting') return true;
      if (!timeLeft()) return false;
      act('escape-' + i, () => press('menu'));
    }
    return s.screen() === 'shooting';
  };

  const ram = {};
  for (const addr of [0x6031e924, 0x6031eee7, 0xa031e924, 0xa031eee7, 0x6031e91f, 0xa031e91f]) {
    try { ram[hex(addr)] = readByte(addr); } catch (e) { ram[hex(addr)] = String(e && e.message || e); }
  }
  emit({
    hook: 'observe', role: 'observe', step: 'setup',
    note: 'Stock image. No overlay. Trace starts before the key. Unique call cap 20000. Routes not wired in this lab are recorded without a press.',
    callCap: CALL_CAP,
    ramAtFlagCandidates: ram,
    routesNotWired: [
      { id: 'ael', reason: '0x120b is only in UI_IN variant 1; the lab board 0 reads variant 0' },
      { id: 'bkt', reason: 'the key matrix has no BKT key' },
      { id: 'lock', reason: 'the producer of 0x0202123d/0x0202123e is unknown' },
    ],
    routesTriedEarlier: ['ok', 'up', 'down', 'left', 'right', 'info', 'js_press', 'js_up', 'delete', 'afmeter', 'lvkey'],
  });
  gate.on = true;
  idle(1000);
  before = null;
  snap('baseline');

  if (timeLeft() && s.screen() === 'shooting') {
    for (const id of ['afmeter', 'ael', 'creative_dial']) {
      if (!timeLeft()) break;
      if (id === 'creative_dial') act('route-creative-dial', () => { s.switch_input('creative_dial', 1); s.camapp.pump(); idle(300); });
      else act('route-' + id, () => press(id));
      if (s.screen() !== 'shooting') escapeShooting();
    }
    act('route-still-movie', () => { s.switch_input('still_movie', 0); s.camapp.pump(); idle(300); });
    if (s.screen() !== 'shooting') escapeShooting();
  }

  if (timeLeft() && s.screen() === 'shooting') {
    const opened = traced('open-up', () => press('up'));
    if (opened.screen === 'direct') {
      act('dial-single', () => dial('main', 1));
      traced('cancel-menu', () => press('menu'));
    }
    escapeShooting();
  }

  if (timeLeft()) {
    act('menu-open', () => press('menu'));
    for (let i = 0; i < 24 && timeLeft(); i++) {
      let pageTexts = [];
      try { pageTexts = walk.read().texts.map((t) => t.text); } catch { pageTexts = []; }
      if (pageTexts.some((t) => String(t).includes('AF Target Settings'))) break;
      act('tab-left-' + i, () => press('left'));
    }
    act('mode-settings-ok', () => press('ok'));
    for (let i = 0; i < 10 && timeLeft(); i++) {
      const row = act('mode-row-' + i, () => {});
      const right = act('mode-row-' + i + '-right', () => press('right'));
      const entered = right.frameHash !== row.frameHash || right.screen !== row.screen || right.customTouched;
      if (entered) {
        act('custom-dial', () => dial('main', 1));
        act('custom-dial-2', () => dial('main', 1));
        act('custom-sub', () => dial('sub', 1));
        act('custom-up', () => press('up'));
        act('custom-right', () => press('right'));
        act('custom-ok', () => press('ok'));
        act('custom-menu', () => press('menu'));
        break;
      }
      if (s.screen() !== 'menu') break;
      act('mode-down-' + i, () => press('down'));
    }
    escapeShooting();
  }

  if (timeLeft() && s.screen() === 'shooting') {
    const prior = arr(0x5a11, 11);
    for (let i = 0; i < 11; i++) writeKey(0x5a11, i, 1);
    const enabled = arr(0x5a11, 11);
    emit({
      hook: 'observe', role: 'observe', step: 'enable-custom-slots',
      note: 'Native setter 0x60063431 wrote 0x5a11 index 0..10 to 1 so the stock direct screen offers C1-C4. Not an overlay.',
      before: prior, after: enabled,
    });
    act('custom-direct-open', () => press('up'));
    let seen = null;
    for (let i = 0; i < 12 && timeLeft() && s.screen() === 'direct'; i++) {
      const row = act('custom-direct-dial-' + i, () => dial('main', 1));
      if (row.zone >= 6 && row.zone <= 9) { seen = row; break; }
    }
    if (seen) act('custom-direct-info', () => press('info'));
    emit({ hook: 'observe', role: 'observe', step: 'custom-direct-result', zone: seen ? seen.zone : null, reached: !!seen });
  }
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: true, deadlineHit: !timeLeft() });
} catch (e) {
  failed = String(e && e.stack ? e.stack : e);
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: false, error: failed });
  process.exitCode = 1;
} finally {
  try { setExecTrace(null); setForceHelper(false); } catch { /* trace already clear */ }
  if (pl.session) pl.close_session();
  writeFileSync(OUT, lines.join('\n') + (lines.length ? '\n' : ''));
}
if (failed) process.exit(1);
